function openAuth(mode="register",message="Busca y compara libremente. Solo necesitas una cuenta para contactar, publicar o guardar."){
  if(mode==="login"){openCredentialAuth("login",null,message);return;}
  openModal(`<div class="modal-inner"><span class="modal-kicker">CUENTA GRATUITA</span><h2 id="modalTitle">¿Cómo usarás Quién Puede?</h2><p class="modal-lead">${message}</p>${roleChooser()}</div>`);
  bindAuthHandlers();
}
function roleChooser(){return `<div class="role-grid"><button class="role-card" data-role="customer"><span>⌕</span><strong>Necesito un servicio</strong><small>Busca, publica tareas y compara cotizaciones.</small></button><button class="role-card" data-role="provider"><span>↗</span><strong>Ofrezco servicios</strong><small>Crea tu perfil, recibe oportunidades y cotiza.</small></button></div><p class="modal-footer-note">Una misma cuenta podrá hacer ambas cosas. ¿Ya tienes cuenta? <button class="text-link" id="switchLogin">Ingresar</button></p>`}
function bindAuthHandlers(){
  document.querySelectorAll("[data-role]").forEach(btn=>btn.addEventListener("click",()=>openCredentialAuth("register",btn.dataset.role)));
  el("switchLogin").addEventListener("click",()=>openAuth("login"));
}
function openCustomerRegistration(){openCredentialAuth("register","customer")}
function openCredentialAuth(mode="register",role=null,message="Usa un método seguro para acceder a tu cuenta."){
  const accountLabel=role==="provider"?"cuenta de empresa":role==="customer"?"cuenta personal":"cuenta";
  openModal(`<div class="modal-inner auth-panel"><span class="modal-kicker">${mode==="login"?'BIENVENIDO DE VUELTA':'REGISTRO SEGURO'}</span><h2 id="modalTitle">${mode==="login"?"Ingresa a Quién Puede":`Crea tu ${accountLabel}`}</h2><p class="modal-lead">${message}</p><div class="social-auth"><button type="button" data-social-auth="google"><b>G</b> Continuar con Google</button><button type="button" data-social-auth="apple"><b>●</b> Continuar con Apple</button></div><div class="auth-divider"><span>o continúa con tu correo</span></div><form class="modal-form" id="credentialForm"><label>Correo electrónico<input id="authEmail" type="email" required autocomplete="email" placeholder="tu@correo.cl"></label><label>Contraseña<input id="authPassword" type="password" required minlength="8" autocomplete="${mode==='login'?'current-password':'new-password'}" placeholder="Mínimo 8 caracteres"></label>${mode==='register'?'<label>Repite tu contraseña<input id="authPasswordConfirm" type="password" required minlength="8" autocomplete="new-password" placeholder="Repite la contraseña"></label>':''}<button class="btn btn-coral full" type="submit">${mode==="login"?'Ingresar':'Crear cuenta y verificar correo'}</button><div class="auth-note"><strong>Versión demostrativa:</strong> el flujo ya está diseñado, pero el envío de correos y los accesos de Google y Apple se activarán al conectar las credenciales de autenticación.</div></form><p class="modal-footer-note">${mode==="login"?'¿Olvidaste tu contraseña? <button class="text-link" id="recoverPassword">Recuperarla</button><br>¿Aún no tienes cuenta? <button class="text-link" id="switchRegister">Crear cuenta</button>':'Ya tengo cuenta: <button class="text-link" id="switchLogin">Ingresar</button>'}</p></div>`);
  document.querySelectorAll("[data-social-auth]").forEach(button=>button.addEventListener("click",()=>continueSocialAuth(button.dataset.socialAuth,mode,role)));
  el("credentialForm").addEventListener("submit",event=>{event.preventDefault();const email=el("authEmail").value.trim(),password=el("authPassword").value;if(mode==="register"&&password!==el("authPasswordConfirm").value){showToast("Las contraseñas no coinciden");return;}if(mode==="login"){const saved=JSON.parse(localStorage.getItem("qp_demo_profile")||"null"),savedEmail=saved?.email||saved?.contact;if(saved&&normalize(savedEmail)===normalize(email)){state.user=saved;sessionStorage.setItem("cs_user",JSON.stringify(saved));updateAccountButton();showDashboard();}else openAuth("register","No encontramos una cuenta demostrativa con ese correo. Puedes crearla ahora.");return;}openCodeVerification({mode,method:"email",contact:email,role,passwordSet:true});});
  const switchId=mode==="login"?"switchRegister":"switchLogin";el(switchId).addEventListener("click",()=>mode==="login"?openAuth("register"):openAuth("login"));
  if(el("recoverPassword"))el("recoverPassword").addEventListener("click",()=>{openModal(`<div class="modal-inner"><span class="modal-kicker">RECUPERAR ACCESO</span><h2 id="modalTitle">Restablece tu contraseña</h2><p class="modal-lead">Ingresa tu correo y te enviaremos un enlace seguro.</p><form class="modal-form" id="recoveryForm"><label>Correo electrónico<input type="email" required placeholder="tu@correo.cl"></label><button class="btn btn-coral full">Enviar enlace</button><div class="auth-note">El envío se habilitará al conectar el servicio de autenticación.</div></form></div>`);el("recoveryForm").addEventListener("submit",event=>{event.preventDefault();showSuccess("Solicitud preparada","Cuando conectemos la autenticación recibirás aquí el enlace real para crear una nueva contraseña.")});});
}
function continueSocialAuth(provider,mode,role){
  if(mode==="login"){const saved=JSON.parse(localStorage.getItem("qp_demo_profile")||"null");if(saved){state.user={...saved,authProvider:provider};sessionStorage.setItem("cs_user",JSON.stringify(state.user));showDashboard();return;}openAuth("register","Selecciona primero cómo usarás la plataforma para completar tu perfil.");return;}
  const auth={contact:`cuenta@${provider}.demo`,method:provider,role,authProvider:provider};showToast(`Continuando con ${provider==="google"?'Google':'Apple'} en modo demostración`);setTimeout(()=>role==="provider"?startProviderOnboarding("basic",1,auth):openCustomerProfile(auth),350);
}
function openCodeVerification(auth){
  const destination=auth.method==="phone"?"tu teléfono":"tu correo";
  openModal(`<div class="modal-inner"><span class="modal-kicker">VERIFICA TU ACCESO</span><h2 id="modalTitle">Ingresa el código</h2><p class="modal-lead">En producción enviaremos 6 dígitos a ${escapeHTML(auth.contact)}. Revisa ${destination}.</p><form class="modal-form" id="codeForm"><label>Código de acceso<input id="accessCode" class="code-input" required inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="one-time-code" placeholder="000000"></label><button class="btn btn-coral full" type="submit">Verificar y continuar</button><div class="auth-note">Para probar este prototipo, escribe cualquier código de 6 números.</div></form><p class="modal-footer-note"><button class="text-link" id="changeContact">Cambiar ${auth.method==="phone"?"teléfono":"correo"}</button></p></div>`);
  el("codeForm").addEventListener("submit",event=>{event.preventDefault();if(auth.mode==="login")completeAuth("Persona demo","customer",{contact:auth.contact,method:auth.method});else auth.role==="provider"?startProviderOnboarding("basic",1,auth):openCustomerProfile(auth);});
  el("changeContact").addEventListener("click",()=>openCredentialAuth(auth.mode,auth.role));
}
function openCustomerProfile(auth={},existing=state.user){
  const current=existing?.role==="customer"?existing:{};
  const suggestedLocation=current.location||state.pendingAction?.task?.location||"";
  const suggestedCoords=current.coords||state.pendingAction?.task?.coords||null;
  openModal(`<div class="modal-inner"><span class="modal-kicker">TU PERFIL</span><h2 id="modalTitle">${current.name?"Actualiza tu ubicación":"Guarda tu ubicación habitual"}</h2><p class="modal-lead">La usaremos para prellenar búsquedas y solicitudes. Siempre podrás cambiarla para un trabajo puntual.</p><form class="modal-form" id="customerProfileForm"><label>Tu nombre<input id="profileName" required autocomplete="name" value="${escapeHTML(current.name||"")}" placeholder="¿Cómo te llamas?"></label><label>Ubicación habitual<div class="input-with-action"><input id="profileLocation" required value="${escapeHTML(suggestedLocation)}" placeholder="Comuna o dirección"><button id="profileUseLocation" type="button"><span>◎</span> Usar mi ubicación</button></div><small class="field-help">Puedes indicar solo tu comuna si prefieres no guardar una dirección exacta.</small></label>${current.name?"":'<label class="check-label"><input type="checkbox" required> Acepto los términos y la política de privacidad del prototipo</label>'}<button class="btn btn-coral full" type="submit">Guardar y continuar</button></form></div>`);
  if(suggestedCoords){el("profileLocation").dataset.lat=suggestedCoords.lat;el("profileLocation").dataset.lng=suggestedCoords.lng;}
  el("profileUseLocation").addEventListener("click",()=>requestUserLocation("profile"));
  el("profileLocation").addEventListener("input",event=>{if(event.isTrusted){delete event.target.dataset.lat;delete event.target.dataset.lng;}});
  el("customerProfileForm").addEventListener("submit",event=>{event.preventDefault();const locationInput=el("profileLocation");const location=locationInput.value.trim();const coords=locationInput.dataset.lat?{lat:Number(locationInput.dataset.lat),lng:Number(locationInput.dataset.lng)}:coordinatesForLocation(location);completeAuth(el("profileName").value.trim(),"customer",{contact:auth.contact||current.contact,method:auth.method||current.method,authProvider:auth.authProvider||auth.method||current.authProvider||"email",location,coords});});
}
function completeAuth(name,role,details={}){
  state.user={name,role,...details};sessionStorage.setItem("cs_user",JSON.stringify(state.user));localStorage.setItem("qp_demo_profile",JSON.stringify(state.user));updateAccountButton();
  if(state.user.location&&!el("locationInput").value){el("locationInput").value=state.user.location;state.location=state.user.location;state.coords=state.user.coords||coordinatesForLocation(state.user.location);el("locationStatus").textContent="Usaremos la ubicación guardada en tu perfil. Puedes cambiarla cuando quieras.";}
  const pending=state.pendingAction;state.pendingAction=null;
  if(pending?.type==="contact"){contactProvider(providers.find(p=>p.id===pending.id));return;}
  if(pending?.type==="favorite"){state.favorites.add(pending.id);localStorage.setItem("cs_favorites",JSON.stringify([...state.favorites]));renderProviders();}
  if(pending?.type==="task"){publishTask(pending.task);return;}
  if(pending?.type==="follow"){state.following.add(pending.id);localStorage.setItem("qp_following",JSON.stringify([...state.following]));renderExplore();showProvider(pending.id);return;}
  if(pending?.type==="savePost"){state.savedPosts.add(pending.id);localStorage.setItem("qp_saved_posts",JSON.stringify([...state.savedPosts]));renderExplore();showPortfolioPost(pending.id);return;}
  if(pending?.type==="likePost"){state.likedPosts.add(pending.id);localStorage.setItem("qp_liked_posts",JSON.stringify([...state.likedPosts]));showPortfolioPost(pending.id);return;}
  if(pending?.type==="commentPost"){addReelComment(pending.id,pending.text);return;}
  if(pending?.type==="chat"){openChat(providers.find(p=>p.id===pending.id),portfolioPosts.find(post=>post.id===pending.postId));return;}
  if(pending?.type==="inbox"){openInbox();return;}
  if(pending?.type==="following"){showFollowing();return;}
  if(pending?.type==="exploreFilter"){state.exploreFilter=pending.filter;renderExplore();closeModal();el("explorar").scrollIntoView({behavior:"smooth"});return;}
  showSuccess(details.location?"Cuenta lista":"Sesión iniciada",details.location?`Bienvenido, ${name}. Tu ubicación quedó disponible para búsquedas y nuevas solicitudes.`:`Bienvenido, ${name}. Ya puedes continuar en esta demostración.`);
}
function updateAccountButton(){
  document.querySelectorAll('[data-open-auth="login"]').forEach(btn=>{if(state.user){btn.innerHTML=btn.closest(".mobile-nav")?'<span>♙</span>Mi panel':`Mi panel`;btn.onclick=e=>{e.preventDefault();showDashboard()}}});
}

function startProviderOnboarding(selectedPlan="basic",step=1,data={}){
  if(step===1&&!data.contact&&!state.user){openCredentialAuth("register","provider");return;}
  if(step===1){openModal(`<div class="modal-inner"><span class="modal-kicker">PUBLICA TUS SERVICIOS</span><h2 id="modalTitle">Crea tu perfil profesional</h2><div class="progress"><i class="active"></i><i></i><i></i></div><form class="modal-form" id="providerStep1"><div class="form-row"><label>Nombre o empresa<input required name="name" placeholder="Ej: Reparaciones Soto"></label><label>RUT<input required name="rut" placeholder="12.345.678-9"></label></div><label>Correo de trabajo<input type="email" required name="email" value="${data.method==='email'?escapeHTML(data.contact||''):''}" placeholder="contacto@empresa.cl"></label><label>Rubro principal<select required name="category">${categories.map(c=>`<option value="${c.id}">${c.name}</option>`).join("")}</select></label><label>Describe lo que haces<textarea required name="description" placeholder="Servicios, experiencia y qué te diferencia"></textarea></label><button class="btn btn-coral full" type="submit">Continuar</button></form></div>`);el("providerStep1").addEventListener("submit",e=>{e.preventDefault();startProviderOnboarding(selectedPlan,2,{...data,...Object.fromEntries(new FormData(e.target))})});return;}
  if(step===2){openModal(`<div class="modal-inner"><span class="modal-kicker">PASO 2 DE 3</span><h2 id="modalTitle">Define dónde atiendes</h2><div class="progress"><i class="active"></i><i class="active"></i><i></i></div><form class="modal-form" id="providerStep2"><div class="form-row"><label>Región principal<select required name="region"><option>Arica y Parinacota</option><option>Tarapacá</option><option>Antofagasta</option><option>Atacama</option><option>Coquimbo</option><option selected>Valparaíso</option><option>Metropolitana</option><option>O'Higgins</option><option>Maule</option><option>Ñuble</option><option>Biobío</option><option>Araucanía</option><option>Los Ríos</option><option>Los Lagos</option><option>Aysén</option><option>Magallanes</option></select></label><label>Comuna base<input required name="city" placeholder="Ej: Quilpué"></label></div><div class="form-row"><label>Radio de atención<select name="radius"><option value="10">10 km</option><option value="25" selected>25 km</option><option value="50">50 km</option><option value="100">100 km</option><option value="9999">Todo Chile</option></select></label><label>Otras comunas o zonas<input name="zones" placeholder="Ej: Viña del Mar, Villa Alemana"></label></div><label class="check-label"><input type="checkbox" name="remote"> También puedo atender de forma remota</label><label>Servicios específicos<input required name="services" placeholder="Ej: filtraciones, calefont, destapes"></label><button class="btn btn-coral full" type="submit">Elegir plan</button></form></div>`);el("providerStep2").addEventListener("submit",e=>{e.preventDefault();startProviderOnboarding(selectedPlan,3,{...data,...Object.fromEntries(new FormData(e.target))})});return;}
  openModal(`<div class="modal-inner"><span class="modal-kicker">PASO 3 DE 3</span><h2 id="modalTitle">Elige tu plan</h2><div class="progress"><i class="active"></i><i class="active"></i><i class="active"></i></div><p class="modal-lead">Basic es gratis para siempre. Premium suma mayor visibilidad, verificación y promoción para personas que buscan tu rubro y zona.</p><label class="plan-option ${selectedPlan==='basic'?'selected':''}"><input type="radio" name="onboardPlan" value="basic" ${selectedPlan==='basic'?'checked':''}><div><strong>Basic · Gratis para siempre</strong><small>Perfil, mensajería, oportunidades y portafolio estándar. No requiere tarjeta.</small></div></label><label class="plan-option ${selectedPlan==='premium'?'selected':''}"><input type="radio" name="onboardPlan" value="premium" ${selectedPlan==='premium'?'checked':''}><div><strong>Premium · $16.990/mes</strong><small>Insignia verificada, prioridad local, historias y reels destacados, alertas, estadísticas y soporte.</small></div></label><div id="paymentBlock" ${selectedPlan==='basic'?'hidden':''}><h3>Asocia un medio de pago</h3><div class="fake-card"><span class="card-number">•••• •••• •••• ••••</span><div class="form-row"><span>MM / AA</span><span>CVV</span></div></div></div><div class="payment-note" id="planBillingNote"></div><button class="btn btn-coral full" id="finishProvider">${selectedPlan==='basic'?'Crear perfil Basic gratis':'Activar Premium'}</button><p class="modal-footer-note">Premium es opcional y puedes cambiar de plan cuando quieras.</p></div>`);
  const updatePlanBilling=()=>{const plan=document.querySelector('input[name="onboardPlan"]:checked').value;el("paymentBlock").hidden=plan==="basic";el("planBillingNote").innerHTML=plan==="basic"?'<strong>Basic:</strong> gratis para siempre, sin tarjeta, permanencia ni cobros posteriores.':'<strong>Premium:</strong> $16.990 mensuales desde la activación. La promoción siempre aparecerá identificada y nunca modificará valoraciones ni puntajes.';el("finishProvider").textContent=plan==="basic"?'Crear perfil Basic gratis':'Activar Premium';};
  document.querySelectorAll('input[name="onboardPlan"]').forEach(input=>input.addEventListener("change",()=>{document.querySelectorAll(".plan-option").forEach(x=>x.classList.remove("selected"));input.closest(".plan-option").classList.add("selected");updatePlanBilling()}));updatePlanBilling();
  el("finishProvider").addEventListener("click",()=>{const plan=document.querySelector('input[name="onboardPlan"]:checked').value;state.user={name:data.name||"Prestador demo",role:"provider",plan,email:data.email||data.contact||"",rut:data.rut||"",category:data.category||"hogar",description:data.description||"",region:data.region||"Valparaíso",location:data.city||"Quilpué",city:data.city||"Quilpué",coords:coordinatesForLocation(data.city||"Quilpué"),radius:Number(data.radius||25),zones:data.zones||"",remote:!!data.remote,services:data.services||"",authProvider:data.authProvider||"email"};sessionStorage.setItem("cs_user",JSON.stringify(state.user));localStorage.setItem("qp_demo_profile",JSON.stringify(state.user));updateAccountButton();showSuccess(plan==="basic"?"Cuenta Basic preparada":"Cuenta Premium preparada",plan==="basic"?"Tu perfil gratuito quedó listo en modo demostración, sin tarjeta ni cobros posteriores.":"Tu perfil Premium quedó listo en modo demostración con posicionamiento patrocinado identificado.",true)});
}

