function opportunityDistance(job){const from=state.user?.coords||coordinatesForLocation(state.user?.location);const km=distanceKm(from,job.coords);return job.remote?"Remoto":km===null?"Distancia por calcular":`${km<10?km.toFixed(1):Math.round(km)} km`;}
